const item = $input.first()?.json || {};

const verifiedChannels = {
  twitter: { id: '6aa054f7cd8b9c702c2f1a35', name: 'Bigcherem', maxLength: 280, requiresMedia: false },
  x: { id: '6aa054f7cd8b9c702c2f1a35', name: 'Bigcherem', maxLength: 280, requiresMedia: false },
  linkedin: { id: '6a5f45a7e2638b94d7a8bc3e', name: 'Joseph Unaogu', maxLength: 3000, requiresMedia: false },
  instagram: { id: '6acf807e778b240e2f07ec61', name: 'unaogujoseph', maxLength: 2200, requiresMedia: true }
};

const rawChannel = String(item.channel || item.metadata?.service || 'twitter').trim().toLowerCase();
const channelKey = rawChannel === 'x' ? 'twitter' : rawChannel;

if (!verifiedChannels[channelKey]) {
  throw new Error('Unsupported social channel: ' + rawChannel + '. Supported: twitter, linkedin, instagram.');
}

const spec = verifiedChannels[channelKey];
const content = String(item.prepared_content || item.caption || item.text || '').trim();

if (!content) {
  throw new Error('Social post content cannot be empty.');
}

if (content.length > spec.maxLength) {
  throw new Error('Content exceeds character limit for ' + spec.name + ' (' + content.length + ' > ' + spec.maxLength + ').');
}

const mediaUrl = item.media_url || item.metadata?.media_url || null;
if (spec.requiresMedia && !mediaUrl) {
  throw new Error('Channel ' + spec.name + ' requires a media URL.');
}

// Approval check: must be approved by human or explicitly authorized
const isApproved = item.status === 'approved' || String(item.metadata?.execution_authorized).toLowerCase() === 'true';
if (!isApproved) {
  throw new Error('Draft is not approved for publishing. Only APPROVED drafts can be dispatched to Buffer.');
}

const draftId = String(item.draft_id || item.metadata?.draft_id || ('draft-' + $execution.id));
const dryRun = item.dry_run !== undefined ? Boolean(item.dry_run) : true;
const saveToDraft = true; // Always save to Buffer draft, never live immediate publish

return [{
  json: {
    channel: channelKey,
    channel_id: spec.id,
    channel_name: spec.name,
    draft_id: draftId,
    content: content,
    media_url: mediaUrl,
    dry_run: dryRun,
    saveToDraft: saveToDraft,
    status: 'APPROVED',
    profile_ids: [spec.id]
  }
}];

const data = $input.first()?.json || {};

// If dry_run is true, simulate Buffer draft creation safely without external call
if (data.dry_run) {
  return [{
    json: {
      success: true,
      dry_run: true,
      draft_id: data.draft_id,
      channel: data.channel,
      channel_id: data.channel_id,
      buffer_id: 'simulated-buffer-' + data.draft_id,
      status: 'BUFFER_DRAFTED',
      note: 'Simulated Buffer draft successfully created (dry_run=true). No public post sent.',
      summary: '📢 Social Draft ' + data.draft_id + ' dispatched to Buffer (' + data.channel_name + ') as DRAFT [DRY RUN].'
    }
  }];
}

// Real mode: passes parameters for Buffer HTTP node
return [{
  json: {
    ...data,
    endpoint: 'https://api.bufferapp.com/1/updates/create.json'
  }
}];
